const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const S={token:localStorage.getItem('tl_token')||'',user:null,page:'overview',dash:{},jobs:[],apps:[],resumes:[],evidence:[]};const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pct=n=>Math.round(Number(n)||0)+'%';const initials=n=>(n||'A').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}async function api(p,o={}){let h={...(o.headers||{})};if(S.token)h.Authorization='Bearer '+S.token;if(o.body&&!(o.body instanceof FormData))h['Content-Type']='application/json';let r;try{r=await fetch('/api'+p,{...o,headers:h})}catch{throw Error('Backend is not responding. Start run.bat and refresh.')}let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Request failed');return d}
const navs={candidate:[['overview','⌂','Overview'],['discover','⌕','Explore jobs'],['applications','▤','Applications'],['profile','◉','My profile']],recruiter:[['overview','⌂','Overview'],['jobs','▦','Open roles'],['candidates','♙','Candidates'],['analytics','▥','Insights']],admin:[['overview','⌂','Overview'],['jobs','▦','Job approvals'],['candidates','♙','Candidates'],['users','♙','Users'],['analytics','▥','Insights']]};
async function begin(){try{if(!S.token)throw 0;S.user=await api('/me');$('#login').classList.add('hidden');$('#signup').classList.add('hidden');$('#shell').classList.remove('hidden');$('#who-name').textContent=S.user.name;$('#who-role').textContent=S.user.role;$('#avatar').textContent=initials(S.user.name);await load();if(!navs[S.user.role].some(([id])=>id===S.page))S.page='overview';drawNav();render()}catch{showLogin()}}
function showLogin(){S.token='';S.user=null;S.page='overview';closeModal();localStorage.removeItem('tl_token');$('#shell').classList.add('hidden');$('#signup').classList.add('hidden');$('#login').classList.remove('hidden')}
async function load(){S.dash=await api('/dashboard');if(S.user.role==='candidate'){[S.jobs,S.apps,S.resumes,S.evidence]=await Promise.all(['/jobs','/applications','/resumes','/evidence'].map(x=>api(x)))}else if(S.user.role==='recruiter'){[S.jobs,S.apps]=await Promise.all(['/jobs','/applications'].map(x=>api(x)))}else{[S.users,S.analytics,S.apps,S.jobs]=await Promise.all(['/admin/users','/admin/analytics','/applications','/jobs'].map(x=>api(x)))}}
function drawNav(){let a=navs[S.user.role];$('#nav').innerHTML=a.map(([id,i,t])=>`<button class="nav ${S.page===id?'active':''}" onclick="go('${id}')"><i>${i}</i><span>${t}</span></button>`).join('')}
function go(p){S.page=p;drawNav();render();scrollTo(0,0)}function title(t){$('#greeting').textContent=t;$('#crumb').textContent=t.toUpperCase()}
function stat(a,b,c){return `<div class="stat"><small>${a}</small><strong>${b}</strong><span>${c}</span></div>`}function head(a,b,c=''){return `<div class="page-head"><div><div class="eyebrow">${S.user.role.toUpperCase()} WORKSPACE</div><h2>${a}</h2><p>${b}</p></div>${c?`<button class="btn btn-green" onclick="${c}">＋ Create a role</button>`:''}</div>`}function empty(a,b){return `<div class="empty"><div style="font-size:23px">${a}</div><b>${b}</b>Nothing to show here yet.</div>`}
function render(){if(!S.user)return;let p=S.page,r=S.user.role;if(p==='overview')r==='candidate'?candidateHome():r==='recruiter'?recruiterHome():adminHome();else if(p==='discover'&&r==='candidate')discover();else if(p==='profile'&&r==='candidate')profile();else if(p==='applications'&&r==='candidate')myApplications();else if(p==='jobs'&&(r==='recruiter'||r==='admin'))jobsPage();else if(p==='candidates'&&(r==='recruiter'||r==='admin'))candidatesPage();else if(p==='analytics')r==='admin'?adminAnalytics():recruiterAnalytics();else if(p==='users'&&r==='admin')usersPage();else {S.page='overview';drawNav();render()}}
function candidateHome(){title('Good '+(new Date().getHours()<12?'morning':'afternoon')+', '+S.user.name.split(' ')[0]);let ready=(S.resumes.some(r=>!r.deleted)?35:0)+(S.evidence.length?35:0)+(S.apps.some(a=>a.assessment_completed)?30:0);$('#view').innerHTML=`<div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><div class="page-head"><div><h2>Build a profile that shows the proof.</h2><p>Turn experience into a story recruiters can understand.</p></div><button class="btn btn-green" onclick="go('discover')">Explore opportunities →</button></div><div class="stats">${stat('Resume versions',S.dash.resumes,'Keep improving your story')}${stat('Applications',S.dash.applications,'Roles you applied for')}${stat('Evidence items',S.dash.evidence,'Projects, certificates, portfolio')}${stat('Open roles',S.jobs.length,'Opportunities to explore')}</div><div class="grid"><section class="panel"><div class="panel-head"><div><h3>Application journey</h3><p>See where each application stands.</p></div><button class="link" onclick="go('applications')">View all →</button></div>${S.apps.length?S.apps.slice(0,5).map(a=>`<div class="row"><div class="company">${e((a.company||'?')[0])}</div><div class="rowgrow"><b>${e(a.job_title)}</b><small>${e(a.company)} · ${e(a.status.replaceAll('_',' '))}</small></div><span class="score">${pct(a.match_score)}</span></div>`).join(''):empty('↗','Your next opportunity awaits')}</section><section class="panel"><div class="panel-head"><div><h3>Profile readiness</h3><p>Small steps strengthen your profile.</p></div></div><div class="detail-score"><strong>${ready}%</strong><small>${S.resumes.length?'A strong start':'Upload your resume'}<br>${S.evidence.length?'Evidence added':'Add project evidence'}<br>${S.apps.some(a=>a.assessment_completed)?'Assessment complete':S.apps.some(a=>a.assessment_available)?'Optional quiz available':'No quiz assigned'}</small></div><button class="btn btn-green" onclick="go('profile')">Manage profile →</button></section></div><div class="notice" style="margin-top:12px">Scores are review aids. Recruiters make decisions; submitted links are not independently verified.</div>`}
function recruiterHome(){title('Welcome back, '+S.user.name.split(' ')[0]);$('#view').innerHTML=`${head('Find the evidence behind every match.','Review candidates with transparent scores and candidate-submitted proof.','openJobModal()')}<div class="stats">${stat('Open roles',S.dash.jobs,'Published roles')}${stat('Applicants',S.dash.applicants,'Applications received')}${stat('To review',S.dash.to_review,'Awaiting review')}${stat('Decisions logged',S.dash.decisions,'Feedback records')}</div><div class="grid"><section class="panel"><div class="panel-head"><div><h3>Applicants to review</h3><p>Open a record to inspect its score evidence.</p></div><button class="link" onclick="go('candidates')">All candidates →</button></div>${S.apps.length?table(S.apps.slice(0,6)):empty('♙','No applicants yet')}</section><section class="panel"><div class="panel-head"><div><h3>Review guide</h3><p>Scores support—not replace—your judgment.</p></div></div><p class="notice">Job match combines role skills, resume text, evidence and an assessment if completed. Trust is a limited summary, not a truth detector.</p><p class="notice warn" style="margin-top:9px">Freshness flags use a small static list. Inspect source documents and do not reject solely by score.</p><p style="font-size:10px;color:var(--muted);margin-top:12px">Feedback is recorded for insights; it does not silently retrain rankings.</p></section></div>`}
function adminHome(){title('Platform overview');$('#view').innerHTML=`${head('Review accounts and monitor activity.','Approve candidates and recruiters before they can sign in.')}<div class="stats">${stat('Users',S.dash.users,'All platform roles')}${stat('Pending approvals',S.dash.pending_users||0,'Candidate and recruiter requests')}${stat('Job postings',S.dash.jobs,'Across the workspace')}${stat('Applications',S.dash.applications,'Candidate submissions')}</div><div class="grid"><section class="panel"><div class="panel-head"><h3>Recent activity</h3><button class="link" onclick="go('analytics')">Insights →</button></div>${table(S.apps.slice(0,7))}</section><section class="panel"><div class="panel-head"><h3>Pending accounts</h3><button class="link" onclick="go('users')">Review all →</button></div>${S.users.filter(x=>x.approval_status==='pending').map(x=>`<div class="row"><div class="rowgrow"><b>${e(x.name)}</b><small>${e(x.role)} · ${e(x.email)}</small></div><button class="btn btn-green" onclick="approveUser(${x.id},'approved')">Approve</button></div>`).join('')||empty('✓','No pending approvals')}</section></div>`}
function table(arr){return `<div class="tablewrap"><table class="table"><thead><tr><th>CANDIDATE</th><th>ROLE</th><th>MATCH</th><th>TRUST*</th><th>TEST</th><th>STATUS</th><th></th></tr></thead><tbody>${arr.map(a=>`<tr><td><b>${e(a.candidate_name||S.user.name)}</b><br><small>${e(a.candidate_email||'')}</small></td><td>${e(a.job_title||'')}</td><td class="score">${pct(a.match_score)}</td><td class="trust">${pct(a.trust_score)}</td><td>${!a.assessment_available?'<span class="tag">Not set</span>':a.assessment_completed?pct(a.assessment_score):'<span class="tag gold">Pending</span>'}</td><td><span class="tag">${e(a.status.replaceAll('_',' '))}</span></td><td><button class="btn" onclick="detail(${a.id})">Review</button></td></tr>`).join('')}</tbody></table></div><small style="color:var(--muted)">*Trust summarizes evidence/consistency; not a truth detector.</small>`}
function discover(){title('Explore opportunities');let q=$('#search-job')?.value||'';let rows=S.jobs.filter(j=>`${j.title} ${j.company} ${j.location}`.toLowerCase().includes(q.toLowerCase()));$('#view').innerHTML=`${head('Roles with room to grow','Find a role that matches what you know—and where you want to go.')}<div style="margin-bottom:13px"><input id="search-job" placeholder="Search roles or companies" value="${e(q)}" style="padding:10px;border:1px solid var(--line);border-radius:8px;width:min(360px,100%)"></div><div class="jobgrid">${rows.length?rows.map(j=>{let applied=S.apps.some(a=>a.job_id===j.id);return `<article class="job"><div class="company">${e(j.company[0])}</div><h3>${e(j.title)}</h3><b style="font-size:10px">${e(j.company)}</b><div class="jobmeta">⌖ ${e(j.location||'Flexible')}　·　${j.applicant_count} applicants</div><p>${e(j.description.slice(0,155))}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)}</span>`).join('')}</div><div class="jobfoot">${j.skills.length} required skills ${applied?'<span class="tag">Applied ✓</span>':`<button class="btn btn-green" onclick="openApply(${j.id})">Apply →</button>`}</div></article>`}).join(''):empty('⌕','No open roles found')}</div>`;$('#search-job').oninput=()=>drawJobCards()}
function drawJobCards(){let q=$('#search-job').value.toLowerCase();$('.jobgrid').innerHTML=S.jobs.filter(j=>`${j.title} ${j.company} ${j.location}`.toLowerCase().includes(q)).map(j=>`<article class="job"><div class="company">${e(j.company[0])}</div><h3>${e(j.title)}</h3><b>${e(j.company)}</b><p>${e(j.description.slice(0,150))}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)}</span>`).join('')}</div><div class="jobfoot">${j.applicant_count} applicants <button class="btn btn-green" onclick="openApply(${j.id})">Apply →</button></div></article>`).join('')||empty('⌕','No open roles found')}
function modal(t,body,actions='',wide=false){$('#modal-root').innerHTML=`<div class="modalbg" onclick="if(event.target===this)closeModal()"><section class="modal ${wide?'wide':''}"><div class="modalhead"><h2>${t}</h2><button class="close" onclick="closeModal()">×</button></div>${body}${actions?`<div class="actions">${actions}</div>`:''}</section></div>`}function closeModal(){$('#modal-root').innerHTML=''}
async function openApply(id){if(!S.resumes.some(r=>!r.deleted)){toast('Upload a resume before applying.');go('profile');return}let j=S.jobs.find(x=>x.id===id);modal('Apply for '+e(j.title),`<p style="font-size:10px;color:var(--muted)">${e(j.company)} · Choose a resume version. You can review score factors after applying.</p><div class="field"><label>Resume version</label><select id="resume-choice">${S.resumes.filter(r=>!r.deleted).map(r=>`<option value="${r.id}">v${r.version} · ${e(r.filename)} · ${r.skills.length} detected skills</option>`).join('')}</select></div><p class="notice">Your score is informational. Evidence links are candidate-submitted and are not verified independently.</p>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="apply(${id})">Submit application →</button>`)}async function apply(id){try{await api(`/jobs/${id}/apply`,{method:'POST',body:JSON.stringify({resume_id:+$('#resume-choice').value})});closeModal();await load();render();toast('Application submitted.')}catch(x){toast(x.message)}}
function myApplications(){title('My applications');$('#view').innerHTML=`${head('Keep your momentum','Review your scores, feedback and next steps.')}<div class="grid"><section class="panel"><div class="panel-head"><h3>Application history</h3></div>${S.apps.length?S.apps.map(a=>`<div class="row"><div class="company">${e((a.company||'?')[0])}</div><div class="rowgrow"><b>${e(a.job_title)}</b><small>${e(a.company)} · ${e(a.status.replaceAll('_',' '))}</small></div><span class="score">${pct(a.match_score)}</span><button class="btn" onclick="detail(${a.id})">Details</button>${(a.resume_deleted||S.resumes.some(r=>!r.deleted&&r.version>a.resume_version))?`<button class="btn btn-soft" onclick="resubmit(${a.id})">Use latest resume</button>`:''}${a.assessment_available&&!a.assessment_completed?`<button class="btn btn-green" onclick="takeTest(${a.id})">Take test</button>`:''}</div>`).join(''):empty('↗','No applications yet')}</section><section class="panel"><div class="panel-head"><h3>Personalized next steps</h3></div>${[...new Set(S.apps.flatMap(a=>a.scores.recommendations||[]))].slice(0,6).map(t=>`<p style="font-size:10px;color:#52685a">→ ${e(t)}</p>`).join('')||'<p style="font-size:10px;color:var(--muted)">Apply to a role for specific suggestions.</p>'}</section></div>`}
function profile(){title('My profile');$('#view').innerHTML=`${head('Make your skills easy to see','Manage resume versions, claimed skills and supporting evidence.')}<div class="grid"><div><section class="panel"><div class="panel-head"><div><h3>Resume versions</h3><p>Upload a replacement anytime. New uploads become the latest version.</p></div><label class="btn btn-green" for="resume-file">＋ Upload resume</label><input id="resume-file" type="file" accept=".pdf,.docx" hidden></div>${S.resumes.length?S.resumes.map(r=>`<div class="row"><div class="company">▤</div><div class="rowgrow"><b>${e(r.filename)}</b><small>Version ${r.version} · ${new Date(r.created).toLocaleDateString()}</small><div class="list">${r.deleted?'<span class="tag gray">File deleted</span>':r.skills.map(x=>`<span class="chip">${e(x)}</span>`).join('')||'<span class="tag gold">No skills detected</span>'}</div></div>${r.deleted?'':`<button class="btn" onclick="deleteResume(${r.id})">Delete</button>`}</div>`).join(''):empty('▤','No resume uploaded')}<div class="notice warn">Scanned PDFs need OCR and aren’t supported. Deleting a resume removes its uploaded file; submitted application score history is retained.</div></section></div><div><section class="panel"><div class="panel-head"><div><h3>Evidence library</h3><p>Candidate-submitted, not independently verified.</p></div><button class="btn btn-green" onclick="evidenceModal()">＋ Add evidence</button></div>${S.evidence.map(x=>`<div class="evidence"><b>${e(x.title)} <span class="tag">${e(x.skill)}</span></b><p>${e(x.kind)} · ${e(x.description)}</p>${x.url?`<a href="${e(x.url)}" target="_blank" rel="noreferrer">Open link ↗</a>`:''}<button class="link" onclick="delEvidence(${x.id})">Remove</button></div>`).join('')||empty('✦','Add project or portfolio proof')}</section><section class="panel"><div class="panel-head"><h3>Resume version progress</h3></div>${S.resumes.map(r=>{let z=S.apps.filter(a=>a.resume_id===r.id),n=z.length?Math.round(z.reduce((a,b)=>a+b.match_score,0)/z.length):0;return `<div class="barrow"><span>Resume v${r.version}</span><div class="bar"><i style="width:${n}%"></i></div><b>${z.length?pct(n):'—'}</b></div>`}).join('')||'<small class="muted">Upload a resume to begin.</small>'}</section></div></div>`;$('#resume-file').onchange=uploadResume}
async function uploadResume(){let f=$('#resume-file').files[0];if(!f)return;let d=new FormData();d.append('file',f);try{let x=await api('/resumes',{method:'POST',body:d});await load();render();toast(`Resume v${x.version} uploaded as your latest version · ${x.skills.length} skills detected. Update existing applications from Applications when ready.`)}catch(x){toast(x.message)}}
function evidenceModal(){modal('Add supporting evidence',`<div class="fgrid"><div class="field"><label>Skill</label><input id="evskill" placeholder="Python"></div><div class="field"><label>Type</label><select id="evkind"><option>project</option><option>github</option><option>certificate</option><option>portfolio</option><option>experience</option><option>course</option></select></div></div><div class="field"><label>Title</label><input id="evtitle" placeholder="Student performance prediction"></div><div class="field"><label>Public URL (optional)</label><input id="evurl" type="url" placeholder="https://..."></div><div class="field"><label>What did you do?</label><textarea id="evdesc" placeholder="Briefly describe your contribution and outcome."></textarea></div><p class="notice warn">The demo records links and descriptions but does not verify authenticity.</p>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveEvidence()">Save evidence</button>`)}async function saveEvidence(){try{await api('/evidence',{method:'POST',body:JSON.stringify({skill:$('#evskill').value,title:$('#evtitle').value,kind:$('#evkind').value,url:$('#evurl').value,description:$('#evdesc').value})});closeModal();await load();render();toast('Evidence added.')}catch(x){toast(x.message)}}async function delEvidence(id){await api('/evidence/'+id,{method:'DELETE'});await load();render();toast('Evidence removed.')}
function candidatesPage(){title('Candidate review');$('#view').innerHTML=`${head('Candidate review','Inspect resume evidence and score factors before recording a decision.')}<section class="panel"><input id="cand-search" placeholder="Search candidate or role" style="padding:9px;border:1px solid var(--line);border-radius:8px;margin-bottom:12px">${S.apps.length?table(S.apps):empty('♙','No applicants yet')}</section>`;$('#cand-search').oninput=()=>{let q=$('#cand-search').value.toLowerCase(),arr=S.apps.filter(a=>(a.candidate_name+a.job_title+a.candidate_email).toLowerCase().includes(q));$('.tablewrap')?.replaceWith(document.createRange().createContextualFragment(table(arr)))}}
async function detail(id){try{let r=await api(`/applications/${id}/detail`),a=S.apps.find(x=>x.id===id),s=a.scores;let body=`<div class="detail-score"><div><strong>${pct(a.match_score)}</strong><small style="display:block">JOB MATCH</small></div><div><strong style="font-size:19px;color:#9b6b1c">${pct(a.trust_score)}</strong><small style="display:block">TRUST*</small></div><div><b>${e(a.job_title)}</b><small style="display:block">${e(a.company)}</small></div></div><div class="fgrid">${[['Required skills',s.skill_coverage],['Text similarity',s.text_similarity],['Evidence provided',s.evidence_coverage],['Assessment',s.assessment]].map(x=>`<div class="field"><small>${x[0]}</small><b>${x[1]==null?'Pending':pct(x[1])}</b></div>`).join('')}</div><h3>Claimed vs supporting evidence</h3><p class="muted" style="font-size:9px">Evidence is candidate-submitted, not independently verified.</p>${s.skill_map.map(m=>`<div class="evidence"><b>${m.resume_match?'✓':'·'} ${e(m.skill)}</b><p>${m.resume_match?'Found in resume':'Not detected'} · ${m.evidence_added?'Evidence item provided':'No evidence added'} ${m.note?'· '+e(m.note):''}</p>${m.freshness?.status==='review'?`<p class="tag gold">⚑ ${e(m.freshness.note)}</p>`:''}</div>`).join('')}<h3 style="margin-top:15px">Score explanation <small class="muted">(transparent factors, not SHAP)</small></h3>${s.contributions.map(x=>`<div class="barrow"><span>${e(x.label)}</span><div class="bar"><i style="width:${x.value}%"></i></div><b>${pct(x.value)}</b></div>`).join('')}<div class="notice">${e(s.human_review)}</div><button class="btn" style="margin-top:9px" onclick="fullResume(${id})">View extracted resume text</button>${['recruiter','admin'].includes(S.user.role)?`<div class="field"><label>Decision</label><select id="decision">${['review','shortlist','interview','selected','not_selected'].map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></div><div class="field"><label>Private review note</label><textarea id="note">${e(a.feedback?.note||'')}</textarea></div><button class="btn btn-green" onclick="saveFeedback(${id})">Save review decision</button>`:''}`;modal('Application review',body,'<button class="btn" onclick="closeModal()">Close</button>',true)}catch(x){toast(x.message)}}
async function saveFeedback(id){try{await api(`/applications/${id}/feedback`,{method:'POST',body:JSON.stringify({decision:$('#decision').value,note:$('#note').value})});closeModal();await load();render();toast('Feedback saved. It will not silently retrain rankings.')}catch(x){toast(x.message)}}
async function takeTest(id){try{let t=await api(`/applications/${id}/assessment`);if(t.completed)return toast('Assessment already submitted: '+pct(t.score));let body=`<p style="font-size:10px;color:var(--muted)">Short role-specific quiz. One attempt. Educational demo, not a validated hiring assessment.</p><form id="testform">${t.questions.map((q,i)=>`<div class="q"><span class="tag">${e(q.skill)}</span><p>${i+1}. ${e(q.question)}</p>${q.options.map((o,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${e(o)}</label>`).join('')}</div>`).join('')}</form><div class="notice warn">Recruiters should not use this quiz result as the sole basis for decisions.</div>`;modal('Role skill check',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="submitTest(${id},${t.questions.length})">Submit answers →</button>`)}catch(x){toast(x.message)}}async function submitTest(id,n){let answers=[];for(let i=0;i<n;i++){let x=$(`input[name="q${i}"]:checked`);if(!x)return toast('Answer every question.');answers.push(+x.value)}try{let z=await api(`/applications/${id}/assessment`,{method:'POST',body:JSON.stringify({answers})});closeModal();await load();render();toast('Assessment recorded: '+pct(z.score))}catch(x){toast(x.message)}}
function jobsPage(){title('Open roles');let own=S.jobs.filter(j=>j.recruiter_id===S.user.id||S.user.role==='admin');$('#view').innerHTML=`${head('Manage open roles','Set role skills and priorities so matches reflect this job.','openJobModal()')}<div class="jobgrid">${own.map(j=>`<article class="job"><div class="company">${e(j.company[0])}</div><h3>${e(j.title)}</h3><div class="jobmeta">${e(j.company)} · ${e(j.location)}</div><p>${e(j.description.slice(0,145))}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)} · ${Math.round(s.weight*100)}%</span>`).join('')}</div><div class="jobfoot">${j.applicant_count} applicants <button class="btn" onclick="closeJob(${j.id})">Close role</button></div></article>`).join('')||empty('▦','No roles published')}</div>`}
function rowSkill(name='',weight='.7',level='intermediate'){return `<div class="formrow"><input class="skname" placeholder="Skill" value="${e(name)}"><select class="skweight"><option value="1" ${Number(weight)===1?'selected':''}>High</option><option value=".8" ${Number(weight)===.8?'selected':''}>Medium</option><option value=".7" ${Number(weight)===.7?'selected':''}>Normal</option><option value=".5" ${Number(weight)===.5?'selected':''}>Low</option></select><select class="sklevel"><option>beginner</option><option ${level==='intermediate'?'selected':''}>intermediate</option><option ${level==='advanced'?'selected':''}>advanced</option></select><button class="close" onclick="this.parentElement.remove()">×</button></div>`}
function openJobModal(){modal('Create a role',`<div class="fgrid"><div class="field"><label>Role title</label><input id="jt" placeholder="Junior AI Engineer"></div><div class="field"><label>Company</label><input id="jc" placeholder="Your organization"></div></div><div class="fgrid"><div class="field"><label>Location</label><input id="jl" placeholder="Bengaluru · Hybrid"></div><div class="field"><label>Seniority</label><select id="jlevel"><option>Entry level</option><option>Junior</option><option>Mid-level</option><option>Senior</option></select></div></div><div class="field"><label>Role description</label><textarea id="jd" placeholder="Describe outcomes, responsibilities and your team."></textarea></div><div class="field"><label>Required skills & importance</label><div id="skills-box">${rowSkill('Python','1')}${rowSkill('SQL','.8')}</div><button class="btn" onclick="addSkill()">＋ Add skill</button></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveJob()">Publish role →</button>`)}function addSkill(){$('#skills-box').insertAdjacentHTML('beforeend',rowSkill())}async function saveJob(){let skills=$$('.formrow').map(r=>({name:r.querySelector('.skname').value.trim(),weight:+r.querySelector('.skweight').value,level:r.querySelector('.sklevel').value})).filter(x=>x.name);try{await api('/jobs',{method:'POST',body:JSON.stringify({title:$('#jt').value,company:$('#jc').value,location:$('#jl').value,description:$('#jd').value,skills})});closeModal();await load();render();toast('Role published.')}catch(x){toast(x.message)}}async function closeJob(id){if(!confirm('Close this role? Existing applications will remain.'))return;try{await api('/jobs/'+id,{method:'DELETE'});await load();render();toast('Role closed.')}catch(x){toast(x.message)}}
function recruiterAnalytics(){title('Recruiting insights');let d={};S.apps.forEach(a=>{let x=a.status||'applied';d[x]=(d[x]||0)+1});$('#view').innerHTML=`${head('Applicant flow & feedback','A lightweight summary of reviewer activity.')}<div class="stats">${stat('Open roles',S.dash.jobs,'Published')}${stat('Applicants',S.dash.applicants,'Applications received')}${stat('Shortlisted',d.shortlist||0,'Recruiter feedback')}${stat('Selected',d.selected||0,'Recruiter feedback')}</div><div class="grid"><section class="panel"><div class="panel-head"><h3>Decision distribution</h3></div>${Object.entries(d).map(([k,v])=>`<div class="barrow"><span>${e(k.replaceAll('_',' '))}</span><div class="bar"><i style="width:${S.apps.length?v/S.apps.length*100:0}%"></i></div><b>${v}</b></div>`).join('')||empty('▥','No decisions yet')}</section><section class="panel"><div class="panel-head"><h3>Feedback learning</h3></div><div class="notice">Decisions are stored for aggregate review. This demo does not silently retrain its ranking model; future model updates need adequate labels and validation.</div></section></div>`}
function adminAnalytics(){title('Platform insights');$('#view').innerHTML=`${head('Platform activity','Aggregate usage for this local demonstration.')}<div class="stats">${stat('Users',S.dash.users,'Accounts')}${stat('Jobs',S.dash.jobs,'All job statuses')}${stat('Applications',S.dash.applications,'Submissions')}${stat('Evidence',S.dash.evidence,'Candidate provided')}</div><div class="grid"><section class="panel"><div class="panel-head"><h3>Accounts by role</h3></div>${S.analytics.roles.map(r=>`<div class="barrow"><span>${e(r.role)}</span><div class="bar"><i style="width:${r.count/S.dash.users*100}%"></i></div><b>${r.count}</b></div>`).join('')}</section><section class="panel"><div class="panel-head"><h3>Recruiter feedback</h3></div>${S.analytics.decisions.map(r=>`<div class="row"><div class="rowgrow"><b>${e(r.decision.replaceAll('_',' '))}</b></div>${r.count}</div>`).join('')||empty('▥','No feedback recorded')}</section></div>`}
function usersPage(){title('Users & access');$('#view').innerHTML=`${head('Review candidate and recruiter accounts','Pending accounts cannot sign in until you approve them.')}<section class="panel">${S.users.map(u=>`<div class="row"><div class="rowgrow"><b>${e(u.name)}</b><small>${e(u.email)} · ${e(u.role)}</small></div><span class="tag ${u.approval_status==='pending'?'gold':u.approval_status==='rejected'?'gray':''}">${e(u.approval_status)}</span>${u.approval_status==='pending'?`<button class="btn btn-green" onclick="approveUser(${u.id},'approved')">Approve</button><button class="btn" onclick="approveUser(${u.id},'rejected')">Reject</button>`:''}</div>`).join('')}</section><div class="notice">Public registration accepts candidate and recruiter requests. Admin access is configured separately for the hosted deployment.</div>`}$('#login-form').onsubmit=async ev=>{ev.preventDefault();try{let d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});S.token=d.token;S.page='overview';closeModal();localStorage.setItem('tl_token',d.token);await begin()}catch(x){toast(x.message)}};$$('[data-demo]').forEach(b=>b.onclick=()=>{let m={candidate:'candidate@demo.com',recruiter:'recruiter@demo.com',admin:'admin@demo.com'};$('#email').value=m[b.dataset.demo];$('#password').value='Demo123!';$('#login-form').requestSubmit()});$('#show-signup').onclick=()=>{$('#login').classList.add('hidden');$('#signup').classList.remove('hidden')};$('#show-login').onclick=()=>{$('#signup').classList.add('hidden');$('#login').classList.remove('hidden')};$('#signup-form').onsubmit=async ev=>{ev.preventDefault();try{let d=await api('/auth/register',{method:'POST',body:JSON.stringify({name:$('#new-name').value,email:$('#new-email').value,password:$('#new-password').value,role:$('#new-role').value})});$('#signup').classList.add('hidden');$('#login').classList.remove('hidden');toast(d.message)}catch(x){toast(x.message)}};$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}catch{}showLogin()};
(async()=>{try{if(S.token)await begin()}catch{showLogin()}})();window.go=go;window.openApply=openApply;window.apply=apply;window.detail=detail;window.takeTest=takeTest;window.submitTest=submitTest;window.openJobModal=openJobModal;window.addSkill=addSkill;window.saveJob=saveJob;window.closeJob=closeJob;window.closeModal=closeModal;window.evidenceModal=evidenceModal;window.saveEvidence=saveEvidence;window.delEvidence=delEvidence;window.saveFeedback=saveFeedback;
function usersPage(){title('Users & access');$('#view').innerHTML=`<div class="page-head"><div><div class="eyebrow">ADMIN WORKSPACE</div><h2>Review candidate and recruiter accounts</h2><p>Pending accounts need approval before they can sign in.</p></div><button class="btn btn-green" onclick="openUserModal()">＋ Add account</button></div><section class="panel">${S.users.map(u=>`<div class="row"><div class="rowgrow"><b>${e(u.name)}</b><small>${e(u.email)} · ${e(u.role)}</small></div><span class="tag ${u.approval_status==='pending'?'gold':u.approval_status==='rejected'?'gray':''}">${e(u.approval_status)}</span>${u.approval_status==='pending'?`<button class="btn btn-green" onclick="approveUser(${u.id},'approved')">Approve</button><button class="btn" onclick="approveUser(${u.id},'rejected')">Reject</button>`:''}<button class="btn" onclick="removeUser(${u.id})">Remove</button></div>`).join('')||empty('♙','No accounts yet')}</section><div class="notice">Accounts added here are approved immediately. Admin access is configured separately.</div>`}
function openUserModal(){modal('Add candidate or recruiter',`<div class="field"><label>Full name</label><input id="admin-user-name" required></div><div class="field"><label>Email address</label><input id="admin-user-email" type="email" required></div><div class="field"><label>Temporary password</label><input id="admin-user-password" type="password" minlength="8" required><small style="color:var(--muted)">At least 8 characters. Share this securely with the user.</small></div><div class="field"><label>Account type</label><select id="admin-user-role"><option value="candidate">Candidate</option><option value="recruiter">Recruiter</option></select></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="createAdminUser()">Create account</button>`)}
async function createAdminUser(){const name=$('#admin-user-name').value.trim(),email=$('#admin-user-email').value.trim(),password=$('#admin-user-password').value,role=$('#admin-user-role').value;if(name.length<2||!email||password.length<8)return toast('Enter a name, valid email and password of at least 8 characters.');try{await api('/admin/users',{method:'POST',body:JSON.stringify({name,email,password,role})});closeModal();await load();render();toast('Account created and approved.')}catch(x){toast(x.message)}}
async function removeUser(id){const user=S.users.find(x=>x.id===id);if(!user||!confirm(`Remove ${user.name}'s account? Their account data will also be deleted.`))return;try{await api('/admin/users/'+id,{method:'DELETE'});await load();render();toast('Account removed.')}catch(x){toast(x.message)}}
window.openUserModal=openUserModal;window.createAdminUser=createAdminUser;window.removeUser=removeUser;
window.addEventListener('storage',ev=>{if(ev.key!=='tl_token')return;if(ev.newValue){S.token=ev.newValue;S.page='overview';closeModal();begin()}else showLogin()});

async function resubmit(id){try{let x=await api('/applications/'+id+'/resubmit',{method:'POST'});await load();render();toast('Application updated with resume v'+x.resume_version+'; retake the role quiz.')}catch(x){toast(x.message)}}
window.resubmit=resubmit;

async function fullResume(id){try{let r=await api('/applications/'+id+'/resume');let body='<pre style="white-space:pre-wrap;font:11px/1.65 sans-serif;background:#f6f8f5;padding:14px;border-radius:9px">'+e(r.text)+'</pre>';modal('Resume text · '+e(r.filename),body,'<button class="btn" onclick="detail('+id+')">Back to review</button>',true)}catch(x){toast(x.message)}}
window.fullResume=fullResume;

async function deleteResume(id){if(!confirm('Delete this uploaded resume file? Application score history will remain.'))return;try{let d=await api('/resumes/'+id,{method:'DELETE'});await load();render();toast(d.message)}catch(x){toast(x.message)}}
async function approveUser(id,status){try{await api('/admin/users/'+id+'/approval',{method:'PATCH',body:JSON.stringify({status})});await load();render();toast(status==='approved'?'Account approved. They can now sign in.':'Account rejected.')}catch(x){toast(x.message)}}
window.deleteResume=deleteResume;window.approveUser=approveUser;

api('/health').then(x=>{if(!x.demo_mode)document.querySelector('.demo')?.classList.add('hidden')}).catch(()=>{});

function usersPage(){title('Users & access');$('#view').innerHTML=`<div class="page-head"><div><div class="eyebrow">ADMIN WORKSPACE</div><h2>Review users and company verification</h2><p>Check recruiter identity and submitted company records before approving job roles.</p></div><button class="btn btn-green" onclick="openUserModal()">＋ Add account</button></div><section class="panel">${S.users.map(u=>`<div class="row"><div class="rowgrow"><b>${e(u.name)}</b><small>${e(u.email)} · ${e(u.role)} · account ${e(u.approval_status)}</small>${u.role==='recruiter'?`<div class="notice" style="margin-top:8px"><b>Company verification: ${e(u.company_verification_status||'unverified')}</b>${u.company_name?`<br>Company: ${e(u.company_name)} · Official email: ${e(u.company_email)}<br>Website: <a href="${e(u.company_website)}" target="_blank" rel="noopener">${e(u.company_website)}</a> · Registration: ${e(u.registration_number)}<br>Address: ${e(u.business_address)}<br><a href="${e(u.proof_url)}" target="_blank" rel="noopener">Open company proof</a>`:'<br>No company details submitted yet.'}</div>`:''}</div>${u.role==='recruiter'&&u.company_verification_status==='pending'?`<button class="btn btn-green" onclick="verifyCompany(${u.id},'approved')">Verify company</button><button class="btn" onclick="verifyCompany(${u.id},'rejected')">Reject company</button>`:''}<span class="tag ${u.approval_status==='pending'?'gold':u.approval_status==='rejected'?'gray':''}">${e(u.approval_status)}</span>${u.approval_status==='pending'?`<button class="btn btn-green" onclick="approveUser(${u.id},'approved')">Approve</button><button class="btn" onclick="approveUser(${u.id},'rejected')">Reject</button>`:''}<button class="btn" onclick="removeUser(${u.id})">Remove</button></div>`).join('')||empty('♙','No accounts yet')}</section>`}
async function verifyCompany(id,status){try{await api(`/admin/users/${id}/company-verification`,{method:'PATCH',body:JSON.stringify({status})});await load();render();toast(status==='approved'?'Company verified.':'Company verification rejected.')}catch(x){toast(x.message)}}
function jobsPage(){title(S.user.role==='admin'?'Job approvals':'Open roles');if(S.user.role==='admin'){$('#view').innerHTML=`${head('Review job requirements','Cross-check each role against the recruiter’s verified company details.')}<section class="panel">${S.jobs.map(j=>`<article class="job" style="margin-bottom:12px"><div class="panel-head"><div><h3>${e(j.title)}</h3><p>${e(j.company)} · ${e(j.location||'Flexible')} · ${j.applicant_count} applicants</p></div><span class="tag ${j.approval_status==='pending'?'gold':j.approval_status==='rejected'?'gray':''}">${e(j.approval_status)}</span></div><p>${e(j.description)}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)} · ${Math.round(s.weight*100)}%</span>`).join('')}</div><div class="notice"><b>Recruiter: ${e(j.recruiter_name)} (${e(j.recruiter_email)})</b><br>Company status: ${e(j.company_verification_status)} · ${e(j.company_name||'No company profile')}<br>${e(j.company_email||'')} · ${e(j.company_website||'')} · Registration ${e(j.registration_number||'')}<br><a href="${e(j.proof_url||'#')}" target="_blank" rel="noopener">Open company proof</a></div>${j.approval_status==='pending'?`<div class="actions"><button class="btn" onclick="reviewJob(${j.id},'rejected')">Reject role</button><button class="btn btn-green" onclick="reviewJob(${j.id},'approved')">Approve role</button></div>`:''}</article>`).join('')||empty('▦','No submitted job roles')}</section>`;return}const user=S.user,status=user.company_verification_status||'unverified';let gate=status!=='approved';$('#view').innerHTML=`<div class="page-head"><div><div class="eyebrow">RECRUITER WORKSPACE</div><h2>Company verification and open roles</h2><p>We verify your company first. Every role then goes to an admin for review.</p></div>${!gate?`<button class="btn btn-green" onclick="openJobModal()">＋ Create a role</button>`:''}</div>${gate?`<section class="panel"><div class="panel-head"><div><h3>Verify your company</h3><p>Submit company details and a public proof link for admin review.</p></div><span class="tag ${status==='pending'?'gold':status==='rejected'?'gray':''}">${e(status)}</span></div>${status==='pending'?`<div class="notice">Company details submitted. You can create roles after an admin verifies the company.</div>`:`<div class="fgrid"><div class="field"><label>Legal company name</label><input id="co-name" value="${e(user.company_name||'')}"></div><div class="field"><label>Company registration number</label><input id="co-reg" value="${e(user.registration_number||'')}"></div></div><div class="fgrid"><div class="field"><label>Company email</label><input id="co-email" type="email" value="${e(user.company_email||'')}"></div><div class="field"><label>Company website</label><input id="co-website" type="url" placeholder="https://example.com" value="${e(user.company_website||'')}"></div></div><div class="field"><label>Business address</label><input id="co-address" value="${e(user.business_address||'')}"></div><div class="field"><label>Public company registration or verification document link</label><input id="co-proof" type="url" placeholder="https://..." value="${e(user.proof_url||'')}"></div><button class="btn btn-green" onclick="submitCompanyVerification()">Submit company for verification</button>`}</section>`:''}<section class="panel"><div class="panel-head"><div><h3>Your submitted roles</h3><p>Candidate visibility begins only after admin approval. Rejected roles can be revised and resubmitted.</p></div></div>${S.jobs.map(j=>`<article class="job" style="margin-bottom:10px"><div class="panel-head"><h3>${e(j.title)}</h3><span class="tag ${j.approval_status==='pending'?'gold':j.approval_status==='rejected'?'gray':''}">${e(j.approval_status)}</span></div><p>${e(j.company)} · ${e(j.location||'Flexible')} · ${j.applicant_count} applicants</p><p>${e(j.description)}</p>${j.approval_status==='rejected'&&!gate?`<button class="btn btn-green" onclick="openJobModal(S.jobs.find(role=>role.id===${j.id}))">Revise & resubmit</button>`:''}</article>`).join('')||empty('▦','No roles submitted')}</section>`}
function openJobModal(job=null){const editing=Boolean(job);modal(editing?'Revise rejected role':'Submit a job role for review',`<div class="notice">${editing?'Update the role details and submit it for admin review again. It will remain hidden from candidates until approved.':'Your company has been verified. An admin must approve this role before candidates can see or apply to it.'}</div><div class="fgrid"><div class="field"><label>Role title</label><input id="jt" placeholder="Junior AI Engineer" value="${e(job?.title||'')}"></div><div class="field"><label>Verified company</label><input id="jc" value="${e(S.user.company_name)}" readonly></div></div><div class="field"><label>Location</label><input id="jl" placeholder="City · Hybrid" value="${e(job?.location||'')}"></div><div class="field"><label>Role description and requirements</label><textarea id="jd" placeholder="Describe responsibilities, qualifications and your team.">${e(job?.description||'')}</textarea></div><div class="field"><label>Required skills & importance</label><div id="skills-box">${job?job.skills.map(skill=>rowSkill(skill.name,String(skill.weight),skill.level||'intermediate')).join(''):rowSkill('Python','1')+rowSkill('SQL','.8')}</div><button class="btn" onclick="addSkill()">＋ Add skill</button></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveJob(${editing?job.id:'null'})">${editing?'Resubmit for approval':'Submit for approval'}</button>`)}
async function submitCompanyVerification(){const payload={company_name:$('#co-name').value.trim(),company_email:$('#co-email').value.trim(),company_website:$('#co-website').value.trim(),registration_number:$('#co-reg').value.trim(),business_address:$('#co-address').value.trim(),proof_url:$('#co-proof').value.trim()};if(Object.values(payload).some(v=>!v))return toast('Complete all company verification fields.');try{await api('/recruiter/company-verification',{method:'POST',body:JSON.stringify(payload)});Object.assign(S.user,payload,{company_verification_status:'pending'});render();toast('Company details submitted for admin verification.')}catch(x){toast(x.message)}}
async function saveJob(id=null){const skills=$$('.formrow').map(r=>({name:r.querySelector('.skname').value.trim(),weight:+r.querySelector('.skweight').value,level:r.querySelector('.sklevel').value})).filter(x=>x.name);try{const result=await api(id?`/jobs/${id}`:'/jobs',{method:id?'PUT':'POST',body:JSON.stringify({title:$('#jt').value.trim(),company:$('#jc').value.trim(),location:$('#jl').value.trim(),description:$('#jd').value.trim(),skills})});closeModal();await load();render();toast(id?'Role revised and resubmitted for admin approval.':result.approval_status==='pending'?'Role submitted. Waiting for admin approval.':'Role published.')}catch(x){toast(x.message)}}
async function reviewJob(id,status){try{await api(`/admin/jobs/${id}/approval`,{method:'PATCH',body:JSON.stringify({status})});await load();render();toast(status==='approved'?'Job approved and visible to candidates.':'Job rejected.')}catch(x){toast(x.message)}}
window.reviewJob=reviewJob;window.openJobModal=openJobModal;window.saveJob=saveJob;

function usersPage(){title('Users & access');$('#view').innerHTML=`<div class="page-head"><div><div class="eyebrow">ADMIN WORKSPACE</div><h2>Review candidate and recruiter accounts</h2><p>Pending accounts need approval before they can sign in.</p></div><button class="btn btn-green" onclick="openUserModal()">＋ Add account</button></div><section class="panel">${S.users.map(u=>`<div class="row"><div class="rowgrow"><b>${e(u.name)}</b><small>${e(u.email)} · ${e(u.role)} · account ${e(u.approval_status)}</small></div><span class="tag ${u.approval_status==='pending'?'gold':u.approval_status==='rejected'?'gray':''}">${e(u.approval_status)}</span>${u.approval_status==='pending'?`<button class="btn btn-green" onclick="approveUser(${u.id},'approved')">Approve</button><button class="btn" onclick="approveUser(${u.id},'rejected')">Reject</button>`:''}<button class="btn" onclick="removeUser(${u.id})">Remove</button></div>`).join('')||empty('♙','No accounts yet')}</section><div class="notice">Accounts added here are approved immediately. Admin access is configured separately.</div>`}

function jobsPage(){title(S.user.role==='admin'?'Job approvals':'Open roles');if(S.user.role==='admin'){$('#view').innerHTML=`${head('Review job requirements','Review role details before deciding whether to publish them.')}<section class="panel">${S.jobs.map(j=>`<article class="job" style="margin-bottom:12px"><div class="panel-head"><div><h3>${e(j.title)}</h3><p>${e(j.company)} · ${e(j.location||'Flexible')} · ${j.applicant_count} applicants</p></div><span class="tag ${j.approval_status==='pending'?'gold':j.approval_status==='rejected'?'gray':''}">${e(j.approval_status)}</span></div><p>${e(j.description)}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)} · ${Math.round(s.weight*100)}%</span>`).join('')}</div><div class="notice"><b>Submitted by: ${e(j.recruiter_name)} (${e(j.recruiter_email)})</b></div>${j.approval_status==='pending'?`<div class="actions"><button class="btn" onclick="reviewJob(${j.id},'rejected')">Reject role</button><button class="btn btn-green" onclick="reviewJob(${j.id},'approved')">Approve role</button></div>`:''}</article>`).join('')||empty('▦','No submitted job roles')}</section>`;return}const own=S.jobs.filter(j=>j.recruiter_id===S.user.id);$('#view').innerHTML=`${head('Manage open roles','Submit roles for admin review. Candidates see them after approval.','openJobModal()')}<div class="jobgrid">${own.map(j=>`<article class="job"><div class="panel-head"><h3>${e(j.title)}</h3><span class="tag ${j.approval_status==='pending'?'gold':j.approval_status==='rejected'?'gray':''}">${e(j.approval_status)}</span></div><div class="jobmeta">${e(j.company)} · ${e(j.location||'Flexible')}</div><p>${e(j.description.slice(0,145))}</p><div class="list">${j.skills.map(s=>`<span class="chip">${e(s.name)} · ${Math.round(s.weight*100)}%</span>`).join('')}</div><div class="jobfoot">${j.applicant_count} applicants ${j.approval_status==='rejected'?`<button class="btn btn-green" onclick="openJobModal(S.jobs.find(role=>role.id===${j.id}))">Revise & resubmit</button>`:''}${j.status==='open'?`<button class="btn" onclick="closeJob(${j.id})">Close role</button>`:''}</div></article>`).join('')||empty('▦','No roles submitted')}</div>`}

function openJobModal(job=null){const editing=Boolean(job);modal(editing?'Revise rejected role':'Create a role',`<div class="notice">${editing?'Update the rejected role and resubmit it for admin review.':'Submit this role for admin review. Candidates can see it after it is approved.'}</div><div class="fgrid"><div class="field"><label>Role title</label><input id="jt" placeholder="Junior AI Engineer" value="${e(job?.title||'')}"></div><div class="field"><label>Company</label><input id="jc" placeholder="Your organization" value="${e(job?.company||'')}"></div></div><div class="field"><label>Location</label><input id="jl" placeholder="City · Hybrid" value="${e(job?.location||'')}"></div><div class="field"><label>Role description and requirements</label><textarea id="jd" placeholder="Describe responsibilities, qualifications and your team.">${e(job?.description||'')}</textarea></div><div class="field"><label>Required skills & importance</label><div id="skills-box">${job?job.skills.map(skill=>rowSkill(skill.name,String(skill.weight),skill.level||'intermediate')).join(''):rowSkill('Python','1')+rowSkill('SQL','.8')}</div><button class="btn" onclick="addSkill()">＋ Add skill</button></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveJob(${editing?job.id:'null'})">${editing?'Resubmit for approval':'Submit for approval'}</button>`)}

// Expanded role assessment: recruiter-authored questions and randomized scored questions.
function assessmentQuestionRow(q={}){const options=q.options?.length?q.options:['Option 1','Option 2'];return `<div class="panel custom-question" style="padding:10px;margin:8px 0"><div class="field"><label>Question</label><textarea class="cq-prompt" placeholder="Ask a question related to this role">${e(q.question||'')}</textarea></div><div class="fgrid"><div class="field"><label>Options separated by |</label><input class="cq-options" value="${e(options.join(' | '))}" placeholder="Option A | Option B | Option C"></div><div class="field"><label>Correct option number</label><select class="cq-answer">${[0,1,2,3,4].map(n=>`<option value="${n}" ${Number(q.answer||0)===n?'selected':''}>${n+1}</option>`).join('')}</select></div></div><button class="btn" type="button" onclick="this.closest('.custom-question').remove()">Remove question</button></div>`}
function addAssessmentQuestion(q={}){$('#assessment-questions').insertAdjacentHTML('beforeend',assessmentQuestionRow(q))}
async function saveJob(id=null){const skills=$$('.formrow').map(r=>({name:r.querySelector('.skname').value.trim(),weight:+r.querySelector('.skweight').value,level:r.querySelector('.sklevel').value})).filter(x=>x.name),assessment_questions=[];for(const row of $$('.custom-question')){const question=row.querySelector('.cq-prompt').value.trim();if(!question)continue;const options=row.querySelector('.cq-options').value.split('|').map(x=>x.trim()).filter(Boolean),answer=+row.querySelector('.cq-answer').value;if(options.length<2||options.length>5||answer>=options.length)return toast('Each custom question needs 2–5 options and a correct option that exists.');assessment_questions.push({question,options,answer})}try{const result=await api(id?`/jobs/${id}`:'/jobs',{method:id?'PUT':'POST',body:JSON.stringify({title:$('#jt').value.trim(),company:$('#jc').value.trim(),location:$('#jl').value.trim(),description:$('#jd').value.trim(),skills,assessment_questions})});closeModal();await load();render();toast(id?'Role and assessment revised; sent for approval.':result.approval_status==='pending'?'Role submitted. Waiting for admin approval.':'Role published.')}catch(x){toast(x.message)}}
async function submitTest(id,n){const answers=[];for(let i=0;i<n;i++){const item=$(`input[name="q${i}"]:checked`);if(!item)return toast('Answer every question.');answers.push(+item.value)}try{const result=await api(`/applications/${id}/assessment`,{method:'POST',body:JSON.stringify({answers})});await load();render();modal('Assessment result',`<div class="detail-score"><strong>${pct(result.score)}</strong><span>Score: ${result.correct} correct out of ${result.total} questions</span></div><p class="notice">Your result is saved and visible to the recruiter with your candidate profile.</p>`,'<button class="btn btn-green" onclick="closeModal()">Done</button>');}catch(x){toast(x.message)}}
window.openJobModal=openJobModal;window.saveJob=saveJob;window.addAssessmentQuestion=addAssessmentQuestion;window.takeTest=takeTest;window.submitTest=submitTest;

// Randomized role assessment with immediate quiz results.
async function takeTest(id){try{const t=await api(`/applications/${id}/assessment`);if(t.available===false){toast('No quiz was added for this role.');return}if(t.completed){modal('Assessment result',`<div class="detail-score"><strong>${pct(t.score)}</strong><span>Final score ? ${t.total} questions</span></div>`,'<button class="btn btn-green" onclick="closeModal()">Close</button>');return}const body=`<p class="notice">${t.questions.length} recruiter-added questions. Your score appears as soon as you submit.</p><form id="testform">${t.questions.map((q,i)=>`<div class="q"><span class="tag">${e(q.skill)}</span><p>${i+1}. ${e(q.question)}</p>${q.options.map((o,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${e(o)}</label>`).join('')}</div>`).join('')}</form><div class="notice warn">Use this score as one review aid, not as the sole basis for a hiring decision.</div>`;modal('Role assessment',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="submitTest(${id},${t.questions.length})">Submit answers</button>`,true)}catch(x){toast(x.message)}}
async function submitTest(id,n){const answers=[];for(let i=0;i<n;i++){const item=$(`input[name="q${i}"]:checked`);if(!item)return toast('Answer every question.');answers.push(+item.value)}try{const result=await api(`/applications/${id}/assessment`,{method:'POST',body:JSON.stringify({answers})});await load();render();modal('Assessment result',`<div class="detail-score"><strong>${pct(result.score)}</strong><span>${result.correct} correct out of ${result.total} questions</span></div><p class="notice">Your result is saved and visible to the recruiter beside your candidate profile.</p>`,'<button class="btn btn-green" onclick="closeModal()">Done</button>')}catch(x){toast(x.message)}}
function table(arr){return `<div class="tablewrap"><table class="table"><thead><tr><th>CANDIDATE</th><th>ROLE</th><th>MATCH</th><th>TRUST*</th><th>QUIZ SCORE</th><th>STATUS</th><th></th></tr></thead><tbody>${arr.map(a=>`<tr><td><b>${e(a.candidate_name||S.user.name)}</b><br><small>${e(a.candidate_email||'')}</small></td><td>${e(a.job_title||'')}</td><td class="score">${pct(a.match_score)}</td><td class="trust">${pct(a.trust_score)}</td><td>${!a.assessment_available?'<span class="tag">Not set</span>':a.assessment_completed?pct(a.assessment_score):'<span class="tag gold">Pending</span>'}</td><td><span class="tag">${e(a.status.replaceAll('_',' '))}</span></td><td><button class="btn" onclick="detail(${a.id})">Review</button></td></tr>`).join('')}</tbody></table></div><small style="color:var(--muted)">Quiz scores are automatic. Review all application evidence before deciding.</small>`}
function myApplications(){title('My applications');$('#view').innerHTML=`${head('Keep your momentum','Review your quiz results and application status.')}<div class="grid"><section class="panel"><div class="panel-head"><h3>Application history</h3></div>${S.apps.length?S.apps.map(a=>`<div class="row"><div class="company">${e((a.company||'?')[0])}</div><div class="rowgrow"><b>${e(a.job_title)}</b><small>${e(a.company)} ? ${e(a.status.replaceAll('_',' '))}</small><div class="list">${a.assessment_available?(a.assessment_completed?`<span class="tag">Quiz ${pct(a.assessment_score)}</span>`:'<span class="tag gold">Quiz pending</span>'):'<span class="tag">No quiz</span>'}</div></div><span class="score">${pct(a.match_score)}</span><button class="btn" onclick="detail(${a.id})">Details</button>${(a.resume_deleted||S.resumes.some(r=>!r.deleted&&r.version>a.resume_version))?`<button class="btn btn-soft" onclick="resubmit(${a.id})">Use latest resume</button>`:''}${a.assessment_available&&!a.assessment_completed?`<button class="btn btn-green" onclick="takeTest(${a.id})">Take test</button>`:''}</div>`).join(''):empty('?','No applications yet')}</section><section class="panel"><div class="panel-head"><h3>Personalized next steps</h3></div>${[...new Set(S.apps.flatMap(a=>a.scores.recommendations||[]))].slice(0,6).map(t=>`<p style="font-size:10px;color:#52685a">? ${e(t)}</p>`).join('')||'<p style="font-size:10px;color:var(--muted)">Apply to a role for specific suggestions.</p>'}</section></div>`}
window.takeTest=takeTest;window.submitTest=submitTest;
// Suggest required skills from role text while keeping recruiter edits independent.
let skillSuggestTimer=null,skillSuggestSequence=0;
function addAutomaticSkill(skill){const box=$('#skills-box'),name=String(skill.name||'').trim(),key=name.toLowerCase();if(!name||$$('.formrow .skname').some(input=>input.value.trim().toLowerCase()===key))return;const html=rowSkill(name,String(skill.weight||.8),skill.level||'intermediate').replace('<div class="formrow">','<div class="formrow" data-auto-suggested="true">');box.insertAdjacentHTML('beforeend',html)}
async function updateSuggestedSkills(){const description=$('#jd')?.value||'',sequence=++skillSuggestSequence;if(description.trim().length<3){$$('.formrow[data-auto-suggested="true"]').forEach(row=>row.remove());return}try{const result=await api('/jobs/suggest-skills',{method:'POST',body:JSON.stringify({description})});if(sequence!==skillSuggestSequence||!$('#skills-box'))return;const suggested=new Set(result.skills.map(s=>s.name.toLowerCase()));$$('.formrow[data-auto-suggested="true"]').forEach(row=>{if(!suggested.has(row.querySelector('.skname').value.trim().toLowerCase()))row.remove()});result.skills.forEach(addAutomaticSkill)}catch{}}
function bindSkillSuggestions(){const description=$('#jd'),box=$('#skills-box');if(!description||!box)return;description.addEventListener('input',()=>{clearTimeout(skillSuggestTimer);skillSuggestTimer=setTimeout(updateSuggestedSkills,450)});const markManual=event=>{const row=event.target.closest('.formrow[data-auto-suggested="true"]');if(row)row.dataset.autoSuggested='false'};box.addEventListener('input',markManual);box.addEventListener('change',markManual)}
function openJobModal(job=null){const editing=Boolean(job),questions=job?.assessment_questions||[];modal(editing?'Revise rejected role':'Create a role',`<div class="notice">${editing?'Update the role and resubmit it for admin review.':'Submit this role for admin review. Candidates can see it after approval.'}</div><div class="fgrid"><div class="field"><label>Role title</label><input id="jt" placeholder="Junior AI Engineer" value="${e(job?.title||'')}"></div><div class="field"><label>Company</label><input id="jc" placeholder="Your organization" value="${e(job?.company||'')}"></div></div><div class="field"><label>Location</label><input id="jl" placeholder="City · Hybrid" value="${e(job?.location||'')}"></div><div class="field"><label>Job description and requirements</label><textarea id="jd" placeholder="Describe responsibilities, required skills and your team.">${e(job?.description||'')}</textarea><small>Relevant skills are suggested automatically as you write. Add or remove skills below.</small></div><div class="field"><label>Required and important skills</label><div id="skills-box">${job?job.skills.map(skill=>rowSkill(skill.name,String(skill.weight),skill.level||'intermediate')).join(''):''}</div><button class="btn" type="button" onclick="addSkill()">＋ Add another skill</button></div><section class="panel"><div class="panel-head"><div><h3>Optional recruiter questions</h3><p>Leave this empty for no candidate quiz.</p></div><button class="btn" type="button" onclick="addAssessmentQuestion()">＋ Add question</button></div><div id="assessment-questions">${questions.map(q=>assessmentQuestionRow(q)).join('')}</div></section>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveJob(${editing?job.id:'null'})">${editing?'Resubmit for approval':'Submit for approval'}</button>`,true);bindSkillSuggestions()}
window.openJobModal=openJobModal;

async function saveJob(id=null){if(($('#jd')?.value||'').trim().length>=3)await updateSuggestedSkills();const skills=$$('.formrow').map(r=>({name:r.querySelector('.skname').value.trim(),weight:+r.querySelector('.skweight').value,level:r.querySelector('.sklevel').value})).filter(x=>x.name),assessment_questions=[];for(const row of $$('.custom-question')){const question=row.querySelector('.cq-prompt').value.trim();if(!question)continue;const options=row.querySelector('.cq-options').value.split('|').map(x=>x.trim()).filter(Boolean),answer=+row.querySelector('.cq-answer').value;if(options.length<2||options.length>5||answer>=options.length)return toast('Each custom question needs 2–5 options and a correct option that exists.');assessment_questions.push({question,options,answer})}if(!skills.length)return toast('Add a required skill, or describe the skill in the job description.');try{const result=await api(id?`/jobs/${id}`:'/jobs',{method:id?'PUT':'POST',body:JSON.stringify({title:$('#jt').value.trim(),company:$('#jc').value.trim(),location:$('#jl').value.trim(),description:$('#jd').value.trim(),skills,assessment_questions})});closeModal();await load();render();toast(id?'Role and assessment revised; sent for approval.':result.approval_status==='pending'?'Role submitted. Waiting for admin approval.':'Role published.')}catch(x){toast(x.message)}}
window.saveJob=saveJob;
